fn global_verbose() -> Arg {
    Arg::new("fsv_verbose")
        .long("verbose")
        .short('v')
        .action(ArgAction::SetTrue)
        .help("print debug info to stderr")
        .help_heading("Global options")
}

// Root flags.
#[derive(Args, Debug, Clone)]
pub struct RootArgs {
    #[arg(help = "fail instead of prompting", long = "no-input")]
    pub no_input: bool,
    #[arg(help = "print debug info to stderr", long = "verbose", short = 'v')]
    pub verbose: bool,
    #[arg(help = "print version and exit", long = "version", short = 'V')]
    pub version: bool,
    #[arg(
        help = "Install completion for the current shell.",
        long = "install-completion"
    )]
    pub install_completion: bool,
    #[arg(
        help = "Show completion for the current shell, to copy it or customize the installation.",
        long = "show-completion"
    )]
    pub show_completion: bool,
}

